    if (relativePathComponents.length == 1) {
        return path + "/" + relativePathComponents[0];
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < pathComponents.length; i++) {
        if (i < pathComponents.length - relativePathComponents.length) {
            sb.append(pathComponents[i]);
        } else {
            sb.append(relativePathComponents[i]);
        }
        sb.append("/");
    }
    return sb.toString();
}

